/// Whether a timeline, calendar or compact chart value is a date or a date-time.
enum CruftFreeTimeKind { date, dateTime }

/// *value* in the session locale, as a date or as a date and its time.
String cruftfreeTimeText(DateTime value, CruftFreeTimeKind kind) {
  final locale = cruftfreeRuntime.session.locale;
  return kind == CruftFreeTimeKind.date ? formatDate(value, locale) : '${formatDate(value, locale)} ${formatTime(value, locale)}';
}

