/// The state a stage of a `steps` is drawn in.
enum CruftFreeStepState { done, current, pending, failed }

/// `steps(data: items, label: s => s.name, state: s => s.state) : states(...)`:
/// the stages in order as the Material [Stepper] a narrow multi-step form uses
/// -- done a check, failed an error mark, done and current active, pending
/// muted. The current stage is announced as selected and, while [pulse] holds
/// (the binding the items come from still polls), its title pulses, unless the
/// platform asks for less motion. [state] reads a stage's state as its wire
/// value and [states] maps every member of its enum to a step state: the
/// analyzer checked the map, so a value it lacks was answered by a server with
/// a member this client was not generated for, and is refused.
class CruftFreeSteps<T> extends StatelessWidget {
  const CruftFreeSteps({super.key, required this.items, required this.label, required this.state, required this.states, this.pulse = false, this.onActivate, this.style});

  final List<T> items;
  final String Function(T item) label;
  final String Function(T item) state;
  final Map<String, CruftFreeStepState> states;
  final bool pulse;
  final void Function(T item)? onActivate;
  final CruftFreeStyle? style;

  CruftFreeStepState _drawnAs(T item) {
    final value = state(item);
    final mapped = states[value];
    if (mapped == null) {
      throw StateError("A steps stage has state '$value', which its states(...) does not map; regenerate the client.");
    }
    return mapped;
  }

  @override
  Widget build(BuildContext context) {
    if (items.isEmpty) {
      return cruftfreeStyled(context, style, const SizedBox.shrink());
    }
    final drawn = [for (final item in items) _drawnAs(item)];
    final current = drawn.indexOf(CruftFreeStepState.current);
    final activate = onActivate;
    return cruftfreeStyled(
      context,
      style,
      Stepper(
        physics: const NeverScrollableScrollPhysics(),
        currentStep: current < 0 ? 0 : current,
        onStepTapped: activate == null ? null : (index) => activate(items[index]),
        controlsBuilder: (context, details) => const SizedBox.shrink(),
        steps: [
          for (var index = 0; index < items.length; index++)
            Step(
              title: Semantics(
                selected: drawn[index] == CruftFreeStepState.current,
                child: _CruftFreePulse(active: pulse && drawn[index] == CruftFreeStepState.current, child: Text(label(items[index]))),
              ),
              content: const SizedBox.shrink(),
              isActive: drawn[index] == CruftFreeStepState.done || drawn[index] == CruftFreeStepState.current,
              state: switch (drawn[index]) {
                CruftFreeStepState.done => StepState.complete,
                CruftFreeStepState.failed => StepState.error,
                CruftFreeStepState.current || CruftFreeStepState.pending => StepState.indexed,
              },
            ),
        ],
      ),
    );
  }
}

/// [child], fading in and out while [active] holds -- nothing moves when the
/// platform asks for less motion.
class _CruftFreePulse extends StatefulWidget {
