class _CruftFreePulseState extends State<_CruftFreePulse> with SingleTickerProviderStateMixin {
  late final AnimationController _controller = AnimationController(vsync: this, duration: const Duration(milliseconds: 800));
  late final Animation<double> _opacity = Tween<double>(begin: 1, end: 0.45).animate(CurvedAnimation(parent: _controller, curve: Curves.easeInOut));

  @override
  void didChangeDependencies() {
    super.didChangeDependencies();
    _follow();
  }

  @override
  void didUpdateWidget(_CruftFreePulse oldWidget) {
    super.didUpdateWidget(oldWidget);
    _follow();
  }

  bool get _moving => widget.active && !(MediaQuery.maybeDisableAnimationsOf(context) ?? false);

  void _follow() {
    if (_moving) {
      if (!_controller.isAnimating) {
        _controller.repeat(reverse: true);
      }
    } else {
      _controller
        ..stop()
        ..value = 0;
    }
  }

  @override
  void dispose() {
    _controller.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) => _moving ? FadeTransition(opacity: _opacity, child: widget.child) : widget.child;
}

/// A `dataTable` row's cells fitted to a header of [width] columns: cut to [width], or
/// padded with empty cells up to it; an absent cell is an empty one. The one rule every
/// client target holds.
List<String> cruftfreeFitRow(List<String?>? row, int width) {
  final cells = [for (final cell in (row ?? const <String?>[]).take(width)) cell ?? ''];
  while (cells.length < width) {
    cells.add('');
  }
  return cells;
}

/// `dataTable(columns: x.columns, rows: x.rows, cells: row => row.cells)`: a table whose header
/// is the column texts and whose rows are each row's cells, fitted to the header by
/// [cruftfreeFitRow]; the derived empty state replaces it while there are no rows.
class CruftFreeDataTable<T> extends StatelessWidget {
  const CruftFreeDataTable({super.key, required this.columns, required this.rows, required this.cells, this.empty, this.style});

  final List<String?> columns;
  final List<T> rows;
  final List<String?>? Function(T row) cells;
  final String? empty;
  final CruftFreeStyle? style;

  @override
  Widget build(BuildContext context) {
    final empty = this.empty;
    if (rows.isEmpty && empty != null) {
      return cruftfreeStyled(context, style, _emptyState(empty, null, const []));
    }
    final width = columns.length;
    final table = DataTable(
      columns: [for (final column in columns) DataColumn(label: Text(column ?? ''))],
      rows: [
        for (final row in rows) DataRow(cells: [for (final cell in cruftfreeFitRow(cells(row), width)) DataCell(Text(cell))]),
      ],
    );
    return cruftfreeStyled(context, style, CruftFreeTableSurface(table: table));
  }
}

/// `gallery(data: items, image: i => i.url, caption: i => i.caption)`.
class CruftFreeGallery<T> extends StatelessWidget {
  const CruftFreeGallery({super.key, required this.items, required this.image, required this.caption, this.onActivate, this.pager, this.style});

  final List<T> items;
  final String? Function(T item) image;
  final String? Function(T item) caption;
  final void Function(T item)? onActivate;
  final PagedBinding<Object?>? pager;
  final CruftFreeStyle? style;

  @override
  Widget build(BuildContext context) {
    final activate = onActivate;
    final gap = CruftFreeTokens.of(context).gap;
    final captionStyle = cruftfreeScaledPart(Theme.of(context).textTheme.bodySmall, cruftfreeFontScale(context, style));
    final content = Wrap(
      spacing: gap,
      runSpacing: gap,
      children: [
        for (final entry in items)
          ConstrainedBox(
            constraints: const BoxConstraints(maxWidth: _galleryTileWidth),
            child: _activatable(_figure(entry, captionStyle), activate == null ? null : () => activate(entry)),
          ),
      ],
    );
    return _paged(context, style, content, pager);
  }

  Widget _figure(T entry, TextStyle? captionStyle) {
    final url = cruftfreeSafeImageUrl(image(entry), cruftfreeRuntime.config.apiBaseUrl.toString());
    final text = caption(entry) ?? '';
    return Column(
      mainAxisSize: MainAxisSize.min,
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        if (url != null) Image.network(url, semanticLabel: text),
        Text(text, style: captionStyle),
      ],
    );
  }
}

